snippet:
New outputs (modules/eks-private/outputs.tf):

output "cluster_endpoint" {
  description = "EKS cluster API server endpoint (used by installer prechecks for connectivity)."
  value       = aws_eks_cluster.this.endpoint
}

output "cluster_ca_base64" {
  description = "Base64-encoded cluster CA data."
  value       = aws_eks_cluster.this.certificate_authority[0].data
}

output "oidc_provider_arn" {
  description = "OIDC provider ARN used for IRSA bindings (e.g., EBS CSI + snapshot controller)."
  value       = aws_iam_openid_connect_provider.this.arn
}

New snapshot policy output (modules/snapshots/outputs.tf):

output "snapshot_controller_policy_json" {
  description = "Rendered IAM policy used by the EBS snapshot controller role (for auditing/support)."
  value       = data.aws_iam_policy_document.snapshot_controller.json
}
